28500:   async createSessionConfig(projectPath, additionalDirectories, mcpServers) {
28501:     const sessionRoots = [projectPath, ...additionalDirectories];
28502:     const activeProvider = this.gatewayConfig ? {
28503:       apiType: gatewayApiTypeFromConfig(this.gatewayConfig),
28504:       baseUrl: this.gatewayConfig.config.base_url
28505:     } : this.getNativeProviderConfig();
28506:     logger.log("Creating session config", {
28507:       projectPath,
28508:       overrideActive: this.gatewayConfig !== null,
28509:       modelProvider: this.getModelProvider(),
28510:       apiType: activeProvider.apiType,
28511:       baseUrl: activeProvider.baseUrl
28512:     });
28513:     const mergedConfig = {
28514:       ...mergeGatewayConfig(this.config, this.gatewayConfig),
28515:       projects: Object.fromEntries(sessionRoots.map((root) => [root, {
28516:         trust_level: "trusted"
28517:       }]))
28518:     };
28519:     const configWithWorkspaceRoots = mergeSandboxWorkspaceWriteRoots(mergedConfig, additionalDirectories);
28520:     if (mcpServers.length === 0) {
28521:       return configWithWorkspaceRoots;
28522:     }
28523:     const requestedServers = mcpServers.map((mcp) => ({
28524:       name: sanitizeMcpServerName(mcp.name),
28525:       server: mcp
28526:     }));
28527:     let serversToConfigure = requestedServers;
28528:     if (shouldDeduplicateMcpConflicts()) {
28529:       const existingNames = await this.getConfigMcpServerNames(projectPath);
28530:       serversToConfigure = requestedServers.filter((mcp) => !existingNames.has(mcp.name));
28531:     }
28532:     if (serversToConfigure.length === 0) {
28533:       return configWithWorkspaceRoots;
28534:     }
28535:     return {
28536:       ...configWithWorkspaceRoots,
28537:       "mcp_servers": Object.fromEntries(serversToConfigure.map((mcp) => [mcp.name, this.createMcpSeverConfig(mcp.server)]))
28538:     };

